package edu.brook.pd;

import org.ascape.util.vis.DrawFeature;
import org.eclipse.draw2d.Graphics;

/**
 * Cooperate Defect Style Java Implementation.
 * 
 * Generated by metaabm system: Oct 13, 2008 10:47:33 PM PDT in project: edu.brook.parent.escape
 */

public class CooperateDefectStyleGraphics extends DrawFeature {

    /**
     * Constructs a new Cooperate Defect Style.
     */

    public CooperateDefectStyleGraphics() {
    }

    // todo, make this a useful value for evaluating compatibility of different versions of generated classes
    private static final long serialVersionUID = 89989998L;

    private String uniqueID;

    public String getUID() {
        return uniqueID;
    }

    public String toString() {
        return "Cooperate Defect Style " + uniqueID;
    }

    enum Shapes {
        rectangle, oval, marker
    };

    Shapes shape = Shapes.rectangle;

    public void draw(Graphics g, Object object, int width, int height) {
        org.ascape.model.HostCell playerRuleCell = (org.ascape.model.HostCell) object;
        if (playerRuleCell.getOccupant() instanceof Player) {
            Player playerRule = (Player) playerRuleCell.getOccupant();
            if (playerRule.getStrategy() == PD2D.COOPERATE) {
                org.eclipse.swt.graphics.Color playerRuleColorBlue = org.eclipse.draw2d.ColorConstants.blue;

                g.setForegroundColor(playerRuleColorBlue);
                g.setBackgroundColor(playerRuleColorBlue);
                shape = shape.oval;
                if (shape == Shapes.oval) {
                    g.fillOval(0, 0, width, height);
                } else if (shape == Shapes.marker) {
                    int d = (int) (width * .25 - 1);
                    int d2 = (int) (width * .5 - 1);
                    g.fillOval(d, d, d2, d2);
                } else if (shape == Shapes.rectangle) {
                    g.fillRectangle(0, 0, width, height);
                }

            }

            if (playerRule.getStrategy() == PD2D.DEFECT) {
                org.eclipse.swt.graphics.Color playerRuleColorRed = org.eclipse.draw2d.ColorConstants.red;

                g.setForegroundColor(playerRuleColorRed);
                g.setBackgroundColor(playerRuleColorRed);
                shape = shape.oval;
                if (shape == Shapes.oval) {
                    g.fillOval(0, 0, width, height);
                } else if (shape == Shapes.marker) {
                    int d = (int) (width * .25 - 1);
                    int d2 = (int) (width * .5 - 1);
                    g.fillOval(d, d, d2, d2);
                } else if (shape == Shapes.rectangle) {
                    g.fillRectangle(0, 0, width, height);
                }

            }

        }
    }
}
